/*
 * CCA Foundations flashcards — fully client-side.
 *
 * Reads cards.json (generated by anki/build_anki.py from flashcards.md). Study a
 * single domain or everything, in order or shuffled, one card at a time. Grading
 * (Again/Hard/Good/Easy) feeds a Leitner box stored in localStorage, so the app
 * can resurface cards that are due or weak. The same deck is downloadable as an
 * Anki import file.
 *
 * Deep links: /flashcards/#D2 (or #Traps, #all, #due, #weak) starts that deck.
 */
(function () {
  "use strict";

  var DECK_FILE = "cca-flashcards.txt";       // downloadable Anki deck (same source)
  var STORAGE_KEY = "cca-cards-progress";      // { cardId: {box, due, reps, last} }
  var DAY = 86400000;
  var BOX_DAYS = { 1: 0, 2: 1, 3: 3, 4: 7, 5: 16 }; // days until a card is due again
  var GRADES = [
    { k: "again", label: "Again" },
    { k: "hard", label: "Hard" },
    { k: "good", label: "Good" },
    { k: "easy", label: "Easy" },
  ];

  var view = document.getElementById("view");
  var DATA = null;            // { total, decks:[{key,label,count}], cards:[...] }
  var PROG = {};              // loaded progress map
  var session = null;
  var keyHandler = null;

  // --- Utilities ---
  function escapeHtml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  function shuffle(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }
  // Stable id from the card front (djb2). Survives reordering; changes only if
  // the card text itself is edited.
  function hashStr(s) {
    var h = 5381, i = s.length;
    while (i) h = (h * 33) ^ s.charCodeAt(--i);
    return (h >>> 0).toString(36);
  }
  function setKeyHandler(fn) {
    if (keyHandler) document.removeEventListener("keydown", keyHandler);
    keyHandler = fn;
    if (fn) document.addEventListener("keydown", fn);
  }

  // --- Progress (Leitner) ---
  function loadProg() {
    try { PROG = JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; }
    catch (e) { PROG = {}; }
  }
  function saveProg() { localStorage.setItem(STORAGE_KEY, JSON.stringify(PROG)); }

  function isDue(card) {
    var p = PROG[card.id];
    return !p || (p.due || 0) <= Date.now();
  }
  function isWeak(card) {
    var p = PROG[card.id];
    return !!p && (p.box || 0) <= 2;
  }
  function grade(card, g) {
    var cur = PROG[card.id] || { box: 0, reps: 0 };
    var base = cur.box || 1, box;
    if (g === "again") box = 1;
    else if (g === "hard") box = Math.max(1, cur.box || 1);
    else if (g === "good") box = Math.min(5, base + 1);
    else box = Math.min(5, base + 2); // easy
    PROG[card.id] = {
      box: box,
      due: Date.now() + BOX_DAYS[box] * DAY,
      reps: (cur.reps || 0) + 1,
      last: Date.now(),
    };
    saveProg();
  }

  function cardsForDeck(key) {
    if (key === "all") return DATA.cards;
    if (key === "__due") return DATA.cards.filter(isDue);
    if (key === "__weak") return DATA.cards.filter(isWeak);
    return DATA.cards.filter(function (c) { return c.deck === key; });
  }

  // --- Picker ---
  function deckButton(key, name, sub, cls) {
    return '<button type="button" class="deck-card ' + (cls || "") + '" data-deck="' + key + '">' +
      '<span class="deck-name">' + escapeHtml(name) + "</span>" +
      '<span class="deck-count">' + sub + "</span></button>";
  }

  function renderPicker() {
    session = null;
    setKeyHandler(null);
    if (window.history && history.replaceState) {
      history.replaceState(null, "", location.pathname + location.search); // drop #deck
    }

    var due = DATA.cards.filter(isDue).length;
    var weak = DATA.cards.filter(isWeak).length;
    var started = DATA.cards.filter(function (c) { return PROG[c.id]; }).length;
    var mastered = DATA.cards.filter(function (c) { return PROG[c.id] && PROG[c.id].box === 5; }).length;

    var srRow = deckButton("__due", "Due for review", due + " card" + (due === 1 ? "" : "s") + " due now", "due");
    if (weak) srRow += deckButton("__weak", "Weak cards", weak + " in boxes 1–2", "weak");

    var decks = DATA.decks.map(function (d) {
      return deckButton(d.key, d.label, d.count + " cards");
    }).join("");

    view.innerHTML =
      '<section class="hero" style="padding-bottom:1rem">' +
        "<h1>Flashcards<br><span class=\"hero-sub\">" + DATA.total + " cards across all domains</span></h1>" +
        '<p class="muted">Reveal each answer, then grade how it went — the app resurfaces what you find hard.</p>' +
      "</section>" +
      '<p class="mastery-summary">' + started + " of " + DATA.total + " started · " +
        mastered + " mastered · <strong>" + due + " due now</strong></p>" +
      '<div class="picker-options">' +
        '<span class="label">Order:</span>' +
        '<button type="button" class="chip chip-active" data-order="ordered">In order</button>' +
        '<button type="button" class="chip" data-order="shuffled">Shuffle</button>' +
        '<span class="spacer" style="flex:1"></span>' +
        '<a class="btn btn-secondary" href="' + DECK_FILE + '" download>↓ Download Anki deck</a>' +
      "</div>" +
      '<p class="lp-h3-like">Spaced repetition</p>' +
      '<div class="deck-grid">' + srRow + "</div>" +
      '<p class="lp-h3-like">By domain</p>' +
      '<div class="deck-grid">' +
        deckButton("all", "All domains", DATA.total + " cards · everything at once", "all") +
        decks +
      "</div>" +
      '<p class="muted" style="font-size:0.85rem">Tip: <code>Space</code> reveals / marks Good · ' +
      "<code>1–4</code> grade · <code>←</code> back · <code>R</code> random.</p>";

    var order = "ordered";
    var chips = view.querySelectorAll(".chip");
    chips.forEach(function (chip) {
      chip.addEventListener("click", function () {
        chips.forEach(function (c) { c.classList.remove("chip-active"); });
        chip.classList.add("chip-active");
        order = chip.dataset.order;
      });
    });
    view.querySelectorAll(".deck-card").forEach(function (btn) {
      btn.addEventListener("click", function () {
        startSession(btn.dataset.deck, order === "shuffled");
      });
    });
  }

  // --- Study session ---
  function sessionLabel(key) {
    if (key === "all") return "All domains";
    if (key === "__due") return "Due for review";
    if (key === "__weak") return "Weak cards";
    var d = DATA.decks.filter(function (x) { return x.key === key; })[0];
    return d ? d.label : key;
  }

  function startSession(deckKey, shuffled) {
    var cards = cardsForDeck(deckKey);
    if (!cards.length) {                 // e.g. nothing due — bounce back politely
      renderEmpty(deckKey);
      return;
    }
    session = {
      key: deckKey,
      label: sessionLabel(deckKey),
      cards: shuffled ? shuffle(cards) : cards.slice(),
      index: 0,
      revealed: false,
      shuffled: !!shuffled,
    };
    setKeyHandler(onKey);
    renderCard();
  }

  function deckLabel(key) {
    var d = DATA.decks.filter(function (x) { return x.key === key; })[0];
    return d ? d.label : key;
  }

  function cardStatus(card) {
    var p = PROG[card.id];
    if (!p) return "New card";
    return "Box " + p.box + "/5 · seen " + p.reps + "×";
  }

  function renderCard() {
    if (!session) return;
    if (session.index >= session.cards.length) return renderComplete();

    var n = session.cards.length, i = session.index, card = session.cards[i];
    var pct = Math.round(((i + (session.revealed ? 1 : 0)) / n) * 100);

    var backBlock = session.revealed
      ? '<hr class="fc-divider"><div class="fc-back">' + card.back + "</div>" +
        '<p class="fc-status">' + cardStatus(card) + "</p>"
      : '<div class="fc-hint">Press <strong>Space</strong> or “Show answer” to reveal.</div>';

    var actionArea = session.revealed
      ? '<div class="grade-row" role="group" aria-label="How did it go?">' +
          GRADES.map(function (g) {
            return '<button type="button" class="grade-btn ' + g.k + '" data-grade="' + g.k + '">' +
              g.label + "</button>";
          }).join("") +
        "</div>" +
        '<div class="fc-controls" style="margin-top:0.6rem">' +
          '<span class="spacer"></span>' +
          '<button type="button" class="btn btn-secondary btn-icon" id="reveal-btn">Hide answer</button>' +
        "</div>"
      : '<div class="fc-controls">' +
          '<button type="button" class="btn btn-secondary btn-icon" id="prev-btn"' + (i === 0 ? " disabled" : "") + ">← Previous</button>" +
          '<span class="spacer"></span>' +
          '<button type="button" class="btn btn-secondary" id="random-btn">🎲 Random</button>' +
          '<button type="button" class="btn btn-primary btn-icon" id="reveal-btn">Show answer</button>' +
        "</div>";

    view.innerHTML =
      '<div class="study-bar">' +
        '<span class="deck-title">' + escapeHtml(session.label) +
          (session.shuffled ? ' <span class="muted" style="font-weight:400">· shuffled</span>' : "") + "</span>" +
        '<span class="progress-text">Card ' + (i + 1) + " of " + n + "</span>" +
      "</div>" +
      '<div class="progress-track"><div class="progress-bar" style="width:' + pct + '%"></div></div>' +
      '<article class="flashcard">' +
        '<div class="fc-head"><span class="q-domain">' + escapeHtml(deckLabel(card.deck)) + "</span>" +
          '<span class="fc-side">' + (session.revealed ? "Answer — grade it" : "Question") + "</span></div>" +
        '<div class="fc-front">' + card.front + "</div>" +
        backBlock +
      "</article>" +
      actionArea +
      '<p class="muted" style="text-align:center;margin-top:1rem">' +
        '<a href="#" id="back-link">← Back to decks</a>' +
        (session.revealed ? ' · <a href="#" id="prev-link">Previous</a> · <a href="#" id="rand-link">Random</a>' : "") +
        (session.shuffled || session.revealed ? "" : ' · <a href="#" id="shuffle-link">Shuffle this deck</a>') +
      "</p>";

    wireCard();
  }

  function wireCard() {
    var reveal = document.getElementById("reveal-btn");
    if (reveal) reveal.addEventListener("click", doReveal);
    var prev = document.getElementById("prev-btn");
    if (prev) prev.addEventListener("click", doPrev);
    var rand = document.getElementById("random-btn");
    if (rand) rand.addEventListener("click", doRandom);

    view.querySelectorAll(".grade-btn").forEach(function (b) {
      b.addEventListener("click", function () { doGrade(b.dataset.grade); });
    });

    var back = document.getElementById("back-link");
    if (back) back.addEventListener("click", function (e) { e.preventDefault(); renderPicker(); });
    var prevLink = document.getElementById("prev-link");
    if (prevLink) prevLink.addEventListener("click", function (e) { e.preventDefault(); doPrev(); });
    var randLink = document.getElementById("rand-link");
    if (randLink) randLink.addEventListener("click", function (e) { e.preventDefault(); doRandom(); });
    var sh = document.getElementById("shuffle-link");
    if (sh) sh.addEventListener("click", function (e) { e.preventDefault(); startSession(session.key, true); });
  }

  function doReveal() { session.revealed = !session.revealed; renderCard(); }
  function doNext() { session.index++; session.revealed = false; renderCard(); }
  function doPrev() {
    if (session.index > 0) { session.index--; session.revealed = false; renderCard(); }
  }
  function doRandom() {
    if (session.cards.length <= 1) return;
    var j;
    do { j = Math.floor(Math.random() * session.cards.length); } while (j === session.index);
    session.index = j; session.revealed = false; renderCard();
  }
  function doGrade(g) {
    grade(session.cards[session.index], g);
    doNext();
  }

  function renderComplete() {
    setKeyHandler(onKeyComplete);
    view.innerHTML =
      '<section class="hero">' +
        "<h1>Deck complete</h1>" +
        '<p class="muted">You went through all ' + session.cards.length + " cards in " +
          escapeHtml(session.label) + ". Graded cards will resurface when they're due.</p>" +
        '<div class="start-form">' +
          '<button type="button" class="btn btn-primary btn-lg" id="restart-btn">Study again</button>' +
        "</div>" +
        '<p class="done-note"><a href="#" id="back-link2">← Back to decks</a></p>' +
      "</section>";
    document.getElementById("restart-btn").addEventListener("click", function () {
      startSession(session.key, session.shuffled);
    });
    document.getElementById("back-link2").addEventListener("click", function (e) {
      e.preventDefault(); renderPicker();
    });
  }

  function renderEmpty(deckKey) {
    setKeyHandler(onKeyComplete);
    var msg = deckKey === "__due" ? "Nothing is due right now — nicely done."
      : deckKey === "__weak" ? "No weak cards yet. Grade some cards first."
      : "That deck is empty.";
    view.innerHTML =
      '<section class="hero"><h1>All caught up</h1>' +
        '<p class="muted">' + msg + "</p>" +
        '<p class="done-note"><a href="#" id="back-link3">← Back to decks</a></p></section>';
    var b = document.getElementById("back-link3");
    if (b) b.addEventListener("click", function (e) { e.preventDefault(); renderPicker(); });
  }

  // --- Keyboard ---
  function onKey(e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (!session.revealed) {
      if (e.key === " " || e.key === "Enter" || e.key === "ArrowRight") { e.preventDefault(); doReveal(); }
      else if (e.key === "ArrowLeft") { e.preventDefault(); doPrev(); }
      else if (e.key === "r" || e.key === "R") { e.preventDefault(); doRandom(); }
      else if (e.key === "Escape") renderPicker();
      return;
    }
    // Revealed: space/right = Good; number keys grade; etc.
    if (e.key === " " || e.key === "Enter" || e.key === "ArrowRight") { e.preventDefault(); doGrade("good"); }
    else if (e.key === "1") { e.preventDefault(); doGrade("again"); }
    else if (e.key === "2") { e.preventDefault(); doGrade("hard"); }
    else if (e.key === "3") { e.preventDefault(); doGrade("good"); }
    else if (e.key === "4") { e.preventDefault(); doGrade("easy"); }
    else if (e.key === "ArrowLeft") { e.preventDefault(); doPrev(); }
    else if (e.key === "r" || e.key === "R") { e.preventDefault(); doRandom(); }
    else if (e.key === "Escape") renderPicker();
  }
  function onKeyComplete(e) { if (e.key === "Escape") renderPicker(); }

  // --- Routing / boot ---
  function deckFromHash() {
    var h = (location.hash || "").replace(/^#\/?/, "");
    if (!h) return null;
    if (h === "due") return "__due";
    if (h === "weak") return "__weak";
    if (h === "all") return "all";
    return DATA.decks.some(function (d) { return d.key === h; }) ? h : null;
  }

  function boot() {
    var hk = deckFromHash();
    if (hk) startSession(hk, false); else renderPicker();
  }

  window.addEventListener("hashchange", function () {
    var hk = deckFromHash();
    if (hk) startSession(hk, false);
  });

  fetch("cards.json")
    .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
    .then(function (data) {
      DATA = data;
      DATA.cards.forEach(function (c) { c.id = hashStr(c.front); });
      loadProg();
      boot();
    })
    .catch(function (err) {
      view.innerHTML = '<section class="hero"><h1>Could not load cards</h1>' +
        '<p class="muted">' + escapeHtml(String(err)) +
        ". This app must be served over HTTP (it works on the published site).</p></section>";
    });
})();
